local LETTER = { "P", "N", "B", "R", "Q", "K" }
Chess.LETTER = LETTER

local FEN_CHAR = {
  P = 1, N = 2, B = 3, R = 4, Q = 5, K = 6,
  p = 7, n = 8, b = 9, r = 10, q = 11, k = 12,
}
local CHAR_OF = {}
for ch, pc in pairs(FEN_CHAR) do CHAR_OF[pc] = ch end
