           empty = { 96, 97 }, safe = { 95, 96, 97 }, flag = FLAG_KCASTLE },
  [WQ] = { colour = WHITE, king = 95, kingTo = 93, rook = 91, rookTo = 94,
           empty = { 92, 93, 94 }, safe = { 95, 94, 93 }, flag = FLAG_QCASTLE },
