-- The letters-on-discs fallback, for squares below SPRITE_PX. A disc is the
-- side's own fill, so a board of letters reads as the same two armies as a
-- board of sprites.
local W_DISC = W_FILL
local W_INK  = {  30,  30,  38 }
local B_DISC = B_FILL
local B_INK  = { 236, 236, 244 }

-- The pieces as TI.Image objects, indexed [type][side], or nil if this runtime
-- will not make them.
--
-- gc:drawImage draws a whole piece in one call where the runs above take about
-- thirty, which is the difference between 32 calls for a full board and ~940.
-- Chess repaints on a key rather than on a timer, so that is a per-keypress
-- cost -- but it is the cost of every keypress, and the arrow keys move a
-- cursor one square at a time.
--
-- The care this needs: image.new's string form is documented only for
-- apilevel < 2.3 (from 2.3 it wants a TI.ResourceHandle built by TI's own
-- SDK), and it was verified on one CX II with tools/probe/imageprobe2.lua --
-- one calculator, one OS. So it is built inside a pcall and the whole thing is
-- all-or-nothing: if any piece fails to build, every piece falls back to the
-- runs, because half a board in one encoding and half in the other would look
-- like a bug rather than a fallback. The runs are not a lesser picture --
-- tools/sprites.py checks the two encodings against the art and against each
-- other, pixel for pixel -- they are only slower.
local sprites = (function()
  if type(image) ~= "table" or type(image.new) ~= "function" then return nil end
  local out = {}
  for t = 1, #SPRITES do
    out[t] = {}
    for side = 1, 2 do
      local built, img = pcall(image.new, SPRITES[t].img[side])
      if not built or not img then return nil end
      out[t][side] = img
    end
  end
  return out
end)()

local SIDE_NAME = { "White", "Black" }

-- The font sizes the Nspire actually has, largest first, for fitting text to
-- a box we only learn the size of at runtime.
local FONT_SIZES = { 24, 16, 12, 11, 10, 9, 7 }

local ui = {
  w = 318, h = 212, cell = 21, board = 168,
  bx = MARGIN + LABEL, by = HUD_H + MARGIN,
  sx = 0, sw = 0, labels = true, sidebar = true, pieceSize = 16,
  sprites = true, spriteInset = 2,
}

local menu = { row = 1, mode = 2, level = 2, side = WHITE, autoFlip = 2 }
local MODE_NAMES = { "2 Players (hot-seat)", "1 Player vs Computer" }
local MODE_SHORT = { "Hot-seat", "vs Computer" }
local ONOFF = { "On", "Off" }

local game = Chess.new({ mode = "bot", botSide = BLACK, state = "ready" })
local ai = nil

-- phase is what the *presentation* is doing, which is not the same question
-- as game.state: the board can be mid-game while the bot is busy thinking,
-- and input has to be ignored throughout that.
local phase      = "idle"  -- idle | thinking
local thinkTicks = 0
local cursor     = Chess.sqOf(5, 2) -- e2: a square someone is about to move
local sel        = nil     -- the square a piece has been picked up from
local dests      = {}      -- legal moves out of sel, for the highlights
local nDests     = 0
local promo      = nil     -- { from, to, choice } while the chooser is up
local flip       = false   -- Black at the bottom
local blink      = 0
local entropy    = 0       -- ticks idled before the first input; seeds the RNG
local legal      = {}      -- scratch for "is this square worth selecting"
local nLegal     = 0

-- ---------------------------------------------------------------- helpers --

local function col(gc, c) gc:setColorRGB(c[1], c[2], c[3]) end

local function level() return Chess.LEVELS[menu.level] end

local function vsBot() return game.mode == "bot" end

-- os.time() alone is a poor seed here: a handheld that has just been reset
-- can report the same value every launch, which would make the bot's choices
-- -- and so every Easy game -- identical every time. Mixing in how long the
-- player sat on the title screen fixes that.
local function reseed()
  local t = 0
  if os and os.time then t = os.time() or 0 end
  if os and os.clock then t = t + math.floor((os.clock() or 0) * 1000) end
  math.randomseed(t + entropy * 7919)
  math.random(); math.random() -- first draws after a reseed are weakly mixed
end

-- True when the machine is waiting on a person rather than on itself.
local function humansTurn()
  return game.state == "playing" and phase == "idle" and not game:isBotTurn()
end

-- ------------------------------------------------------- board <-> screen --
--
-- (col, row) are cells of the drawn grid, 0..7 from the top left. Which
-- square that is depends on which way round the board is, and these two are
-- exact inverses of each other -- everything else works in squares.

local function squareAt(c, r)
  if flip then return Chess.sqOf(8 - c, r + 1) end
  return Chess.sqOf(c + 1, 8 - r)
end

local function cellOf(sq)
  local f, r = Chess.fileOf(sq), Chess.rankOf(sq)
  if flip then return 8 - f, r - 1 end
  return f - 1, 8 - r
end

-- ------------------------------------------------------------- selection --

local function clearSelection()
  sel, nDests = nil, 0
end

local function selectAt(sq)
  local pc = game.board[sq]
  if pc == Chess.EMPTY or Chess.COLOR[pc] ~= game.side then return false end
  local n = game:legalMovesFrom(sq, dests)
  if n == 0 then return false end
  sel, nDests = sq, n
  return true
end

-- The move from the selected square to `sq`, or nil. Promotions come back as
-- the queen version; the chooser swaps in whichever piece the player picks.
local function moveTo(sq)
  for i = 1, nDests do
    if Chess.moveTo(dests[i]) == sq then return dests[i] end
  end
  return nil
end

local function promotesTo(sq)
  local n = 0
  for i = 1, nDests do
    if Chess.moveTo(dests[i]) == sq and Chess.movePromo(dests[i]) ~= 0 then n = n + 1 end
  end
  return n > 1
end

-- ----------------------------------------------------------- turn plumbing --

-- Hands the bot the position and lets on.timer() feed it from there.
local function startThinking()
  ai = Chess.AI.fromLevel(game, menu.level, { rand = game.rand })
  thinkTicks = 0
  phase = "thinking"
end

local function afterMove()
  clearSelection()
  promo = nil
  if game:isOver() then
    phase = "idle"
    return
  end
  -- Hot-seat play on one calculator means the two players sit on the same
  -- side of the screen, so turning the board round between turns is the
  -- closest thing to each of them getting their own view.
  if not vsBot() and menu.autoFlip == 1 then flip = (game.side == BLACK) end
  if game:isBotTurn() then startThinking() else phase = "idle" end
end

local function playMove(m)
  if not game:play(m) then return false end
  cursor = Chess.moveTo(m)
  afterMove()
  return true
end

local function newRound()
  reseed()
  game:reset({
    mode = (menu.mode == 1) and "hotseat" or "bot",
    botSide = (menu.side == WHITE) and BLACK or WHITE,
  })
  ai = nil
  phase, thinkTicks = "idle", 0
  clearSelection()
  promo = nil
  flip = (menu.mode == 2) and (menu.side == BLACK) or false
  cursor = Chess.sqOf(5, flip and 7 or 2)
  if game:isBotTurn() then startThinking() end
end

local function toMenu()
  if ai then ai:cancel() end
  ai = nil
  -- Clear the board on the way out. Leaving an abandoned game showing behind
  -- the title panel invites the player to think it is still theirs to finish.
  game:reset({})
  game.state = "ready"
  phase = "idle"
  clearSelection()
  promo = nil
end

-- Undo. In hot-seat that is one ply; against the bot it is two, because
-- taking back only the bot's reply would just hand it the same position and
-- get the same move -- what the player means is "let me play that again".
local function undo()
  if game.state ~= "playing" and not game:isOver() then return end
  if phase == "thinking" then
    if ai then ai:cancel() end
    phase = "idle"
  end
  if not game:takeback() then return end
  if vsBot() and game:isBotTurn() then game:takeback() end
  ai = nil
  clearSelection()
  promo = nil
  local last = game:lastMove()
  cursor = last and last.to or cursor
  phase = "idle"
end

local function togglePause()
  -- Pausing mid-search is fair game and throws the search away; the bot
  -- starts over on resume.
  if game.state == "playing" then
    if phase == "thinking" then
      if ai then ai:cancel() end
      phase = "idle"
    end
    game.state = "paused"
  elseif game.state == "paused" then
    game.state = "playing"
    if game:isBotTurn() then startThinking() end
  end
end

-- --------------------------------------------------------------- lifecycle --

-- Called before the first paint, and again if the window is resized -- which
-- on a handheld means never, but the computer software can resize freely.
-- The board is always 8x8, so a resize only ever changes the scale: unlike
-- Snake, there is no reason for it to disturb a game in progress.
function on.resize(w, h)
  ui.w, ui.h = w, h

  -- Try the full layout -- coordinates down two edges, sidebar to the right --
  -- and give each of them up in turn if the squares would get too small to
  -- play on. The handheld always affords all of it; the computer software can
  -- be dragged smaller than any of it.
  --
  -- The reserves include the moulded rim on all four sides, so the board plus
  -- its frame is what gets fitted, not the squares alone.
  local function fit(labels, sidebar)
    local reserveW = RIM * 2 + 2 + (labels and LABEL or 0)
      + (sidebar and (GAP + SIDEBAR_MIN + MARGIN) or 0)
    local reserveH = HUD_H + RIM * 2 + 2 + (labels and LABEL or 0)
    local cell = math.floor(math.min((w - reserveW) / 8, (h - reserveH) / 8))
    if cell > CELL_MAX then cell = CELL_MAX end
    return cell, reserveW, reserveH
  end

  local labels, sidebar = true, true
  local cell = fit(labels, sidebar)
  if cell < LABEL_CELL then labels = false; cell = fit(labels, sidebar) end
  if cell < CELL_MIN then sidebar = false; cell = fit(labels, sidebar) end
  if cell < CELL_MIN then
    -- Below the smallest playable board, drop everything else and take
    -- whatever squares are left. Shrinking past the minimum beats painting
    -- over the edge: the Nspire clips silently, so half a board that is
    -- invisible is worse than a whole one that is too small to enjoy.
    labels, sidebar = false, false
    cell = CELL_MIN
    local hard = math.floor(math.min((w - RIM * 2 - 2) / 8, (h - HUD_H - RIM * 2 - 2) / 8))
    if cell > hard then cell = hard end
    if cell < 1 then cell = 1 end
  end

  local _, reserveW, reserveH = fit(labels, sidebar)
  ui.cell, ui.labels = cell, labels
  ui.board = cell * 8
  ui.bx = RIM + 1 + (labels and LABEL or 0)
  ui.by = HUD_H + RIM + 1
    + math.max(0, math.floor((h - reserveH - ui.board) / 2))

  ui.sx = ui.bx + ui.board + GAP
  ui.sw = w - ui.sx - MARGIN
  ui.sidebar = sidebar and ui.sw >= SIDEBAR_MIN
  if not ui.sidebar then
    -- No sidebar to make room for, so centre what is left.
    ui.bx = math.max(RIM + 1, math.floor((w - ui.board) / 2))
    ui.sw = 0
  end

  -- The sprites are a fixed 16x16 and there is no scaling in this sandbox, so
  -- they are drawn at native size centred in the square. Anything smaller than
  -- that falls back to letters rather than to a cropped piece.
  ui.sprites = cell >= SPRITE_PX
  ui.spriteInset = math.floor((cell - SPRITE_PX) / 2)

  -- The largest supported font whose cap height still leaves a ring of disc
  -- visible around it. Sizes are chosen from the list the OS actually has,
  -- never computed, because anything else is silently rejected. Only the
  -- letter fallback uses this.
  ui.pieceSize = FONT_SIZES[#FONT_SIZES]
  for _, sz in ipairs(FONT_SIZES) do
    if sz <= cell - 5 then ui.pieceSize = sz; break end
  end

  platform.window:invalidate()
end

timer.start(BASE_TICK)

function on.timer()
  blink = blink + 1
  local dirty = false

  if game.state == "ready" or game.state == "paused" then
    entropy = entropy + 1
    if blink % 8 == 0 then dirty = true end

  elseif phase == "thinking" then
    thinkTicks = thinkTicks + 1
    local mv = ai:think(TICK_NODES)

    -- The turn is capped in ticks, not in nodes, because how many nodes fit
    -- in a tick depends on a machine this code cannot measure. Whatever depth
    -- finished by now is the one that plays.
    if not mv and thinkTicks >= level().thinkTicks then
      mv = ai:stop()
    end

    -- An instant answer -- a forced mate, or a one-move game -- would
    -- otherwise flash past with the board apparently moving on its own, so
    -- hold the indicator up for a few ticks either way.
    if mv and thinkTicks >= MIN_THINK_TICKS then
      phase = "idle"
      if not playMove(mv) then afterMove() end
    elseif not mv and ai.done then
      -- The search says there is no move: the game is already over, and
      -- updateResult will have said so. Do not spin.
      phase = "idle"
    end
    dirty = true

  elseif game:isOver() then
    if blink % 8 == 0 then dirty = true end
  end

  if dirty then platform.window:invalidate() end
end

function on.deactivate()
  -- Losing focus mid-search would leave the bot holding a half-finished
  -- search across an unknown gap in time; pausing throws it away cleanly.
  if game.state == "playing" then togglePause() end
  platform.window:invalidate()
end

-- ------------------------------------------------------------------- input --

local function menuKey(key)
  local rows = 4
  if key == "up" then
    menu.row = ((menu.row - 2) % rows) + 1
  elseif key == "down" then
    menu.row = (menu.row % rows) + 1
  elseif key == "left" or key == "right" then
    local d = (key == "right") and 1 or -1
    if menu.row == 1 then
      menu.mode = (menu.mode == 1) and 2 or 1
    elseif menu.row == 2 then
      menu.level = ((menu.level - 1 + d) % #Chess.LEVELS) + 1
    elseif menu.row == 3 then
      menu.side = (menu.side == WHITE) and BLACK or WHITE
    else
      menu.autoFlip = (menu.autoFlip == 1) and 2 or 1
    end
  end
end

local function moveCursor(key)
  local c, r = cellOf(cursor)
  if key == "left" then c = c - 1
  elseif key == "right" then c = c + 1
  elseif key == "up" then r = r - 1
  elseif key == "down" then r = r + 1
  else return end
  if c < 0 or c > 7 or r < 0 or r > 7 then return end -- the board does not wrap
  cursor = squareAt(c, r)
end

local function confirm()
  if game.state == "ready" then
    newRound()
    return
  elseif game.state == "paused" then
    togglePause()
    return
  elseif game:isOver() then
    -- One press replays, so a match is a keypress apart; esc goes to the menu.
    newRound()
    return
  end

  if promo then
    local m = Chess.encode(promo.from, promo.to,
      Chess.PROMO_PIECES[promo.choice], Chess.FLAG_NORMAL)
    promo = nil
    playMove(m)
    return
  end

  if not humansTurn() then return end

  if sel then
    local m = moveTo(cursor)
    if m then
      if promotesTo(cursor) then
        -- Four pieces to choose between, so ask rather than assume a queen:
        -- underpromotion to a knight is the one that wins games.
        promo = { from = sel, to = cursor, choice = 1 }
        clearSelection()
      else
        playMove(m)
      end
    elseif cursor == sel then
      clearSelection()
    elseif not selectAt(cursor) then
      clearSelection()
    end
  else
    selectAt(cursor)
  end
end

function on.arrowKey(key)
  if game.state == "ready" then
    menuKey(key)
  elseif promo then
    if key == "left" or key == "up" then
      promo.choice = ((promo.choice - 2) % 4) + 1
    elseif key == "right" or key == "down" then
      promo.choice = (promo.choice % 4) + 1
    end
  elseif game.state == "paused" or game:isOver() then
    -- Arrows do nothing behind an overlay; enter is the way out.
  elseif humansTurn() then
    moveCursor(key)
  end
  platform.window:invalidate()
end

function on.enterKey()
  confirm()
  platform.window:invalidate()
end

function on.escapeKey()
  if promo then
    promo = nil
  elseif game.state == "ready" then
    -- Already home.
  elseif sel then
    clearSelection()
  elseif game:isOver() then
    toMenu()
  else
    togglePause()
  end
  platform.window:invalidate()
end

function on.charIn(ch)
  ch = string.lower(ch or "")
  if ch == " " then
    confirm()
  elseif ch == "u" then
    undo()
  elseif ch == "f" then
    flip = not flip
  elseif ch == "r" then
    if game.state ~= "ready" then newRound() end
  elseif ch == "m" then
    toMenu()
  elseif ch == "p" then
    if game.state ~= "ready" then togglePause() end
  end
  platform.window:invalidate()
end

-- Tapping a square is the same as moving the cursor there and pressing enter,
-- which is what the touchpad and the computer software's mouse want.
function on.mouseDown(x, y)
  if game.state ~= "playing" or promo then
    confirm()
  else
    local c = math.floor((x - ui.bx) / ui.cell)
    local r = math.floor((y - ui.by) / ui.cell)
    if c >= 0 and c <= 7 and r >= 0 and r <= 7 then
      if humansTurn() then
        cursor = squareAt(c, r)
        confirm()
      end
    end
  end
  platform.window:invalidate()
end

-- ----------------------------------------------------------------- drawing --

-- Sets the largest supported font the text fits `maxW` in, and returns it.
-- Font metrics are not knowable until runtime, so every box on screen is
-- sized from the font rather than from a character count.
local function fitFont(gc, text, maxW, style)
  local size = FONT_SIZES[#FONT_SIZES]
  for _, s in ipairs(FONT_SIZES) do
    gc:setFont("sansserif", style or "r", s)
    size = s
    if gc:getStringWidth(text) <= maxW then break end
  end
  return size
end

local function drawHud(gc)
  col(gc, HUD_BG); gc:fillRect(0, 0, ui.w, HUD_H)
  col(gc, HUD_RULE); gc:drawLine(0, HUD_H - 1, ui.w, HUD_H - 1)

  gc:setFont("sansserif", "b", 10)
  local titleW = gc:getStringWidth("CHESS")

  local right = MODE_SHORT[menu.mode]
  if menu.mode == 2 then right = right .. "  " .. level().name end
  gc:setFont("sansserif", "r", 10)
  local rx = ui.w - gc:getStringWidth(right) - MARGIN

  -- The mode and level matter more than the title, so the title is what
  -- yields when a narrow window or a wider font pushes them together.
  if rx > titleW + 12 then
    gc:setFont("sansserif", "b", 10)
    col(gc, ACCENT); gc:drawString("CHESS", MARGIN, 3, "top")
    gc:setFont("sansserif", "r", 10)
  end
  col(gc, INK_DIM); gc:drawString(right, math.max(2, rx), 3, "top")
end

-- The 64 squares in two colour changes: fill the whole board dark, then paint
-- the light squares over it. Setting a colour is a call, and doing it per
-- square would be sixty-four of them every frame.
local function drawSquares(gc)
  local bx, by, cell, n = ui.bx, ui.by, ui.cell, ui.board
  col(gc, RIM_COL); gc:fillRect(bx - RIM, by - RIM, n + RIM * 2, n + RIM * 2)
  col(gc, DARK); gc:fillRect(bx, by, n, n)
  col(gc, LIGHT)
  for r = 0, 7 do
    for c = 0, 7 do
      if Chess.isLight(squareAt(c, r)) then
        gc:fillRect(bx + c * cell, by + r * cell, cell, cell)
      end
    end
  end
end

local function fillSquare(gc, sq, light, dark)
  local c, r = cellOf(sq)
  col(gc, light and (Chess.isLight(sq) and light or dark) or dark)
  gc:fillRect(ui.bx + c * ui.cell, ui.by + r * ui.cell, ui.cell, ui.cell)
end

local function drawHighlights(gc)
  local last = game:lastMove()
  if last then
    fillSquare(gc, last.from, LIGHT_LAST, DARK_LAST)
    fillSquare(gc, last.to, LIGHT_LAST, DARK_LAST)
  end
  if sel then fillSquare(gc, sel, LIGHT_SEL, DARK_SEL) end
  -- A king in check is the one thing on this board a player must not miss, so
  -- it outranks every other highlight and is painted in a colour used nowhere
  -- else on the screen. It stays up after mate, where it is the answer to
  -- "why is that the end" -- which is exactly when a beginner asks.
  if game.state ~= "ready" and game:inCheck() then
    fillSquare(gc, game:kingSq(game.side), nil, CHECK_SQ)
  end
end

-- Paints one sprite layer -- every piece of one side, one run list each -- in
-- a single colour. Called four times a frame, which is the whole reason the
-- runs are grouped this way: setting a colour is a call, and a thousand rects
-- in four colours costs four of them rather than a thousand.
local function drawRuns(gc, runs, x, y)
  for k = 1, #runs, 3 do
    gc:fillRect(x + runs[k + 1], y + runs[k], runs[k + 2], 1)
  end
end

-- One piece at an arbitrary spot: one blit, or rim then silhouette where the
-- images could not be built. Used by the promotion chooser, which shows the
-- four pieces exactly as they will look on the board.
local function drawSprite(gc, pieceType, side, x, y)
  if sprites then
    gc:drawImage(sprites[pieceType][side], x, y)
    return
  end
  local sprite = SPRITES[pieceType]
  col(gc, (side == WHITE) and W_EDGE or B_EDGE)
  drawRuns(gc, sprite.edge, x, y)
  col(gc, (side == WHITE) and W_FILL or B_FILL)
  drawRuns(gc, sprite.fill, x, y)
end

local function drawSpriteLayer(gc, side, layer, colour, inset)
  local cell, bx, by = ui.cell, ui.bx, ui.by
  local list, cnt = game.plist[side], game.pcount[side]
  col(gc, colour)
  for i = 1, cnt do
    local sq = list[i]
    local c, r = cellOf(sq)
    drawRuns(gc, SPRITES[Chess.TYPE[game.board[sq]]][layer],
      bx + c * cell + inset, by + r * cell + inset)
  end
end

-- The fallback for squares too small for the art: a letter on a disc.
--
-- Text is anchored "top" and centred by hand from getStringHeight, here and
-- everywhere else in this file. The Nspire's "middle" anchor would do the
-- vertical half itself, but the preview renderer draws from the top left, so
-- anchoring by hand is what keeps `make screenshots` honest about the layout.
local function drawLetterPieces(gc)
  local cell, bx, by = ui.cell, ui.bx, ui.by
  local d = math.max(2, cell - 4)
  local off = math.floor((cell - d) / 2)
  gc:setFont("sansserif", "b", ui.pieceSize)

  for side = 1, 2 do
    local list, cnt = game.plist[side], game.pcount[side]
    col(gc, (side == WHITE) and W_DISC or B_DISC)
    for i = 1, cnt do
      local c, r = cellOf(list[i])
      gc:fillArc(bx + c * cell + off, by + r * cell + off, d, d, 0, 360)
    end
    col(gc, (side == WHITE) and W_INK or B_INK)
    for i = 1, cnt do
      local sq = list[i]
      local ch = Chess.LETTER[Chess.TYPE[game.board[sq]]]
      local c, r = cellOf(sq)
      -- Centred, but never centred *out* of the square: on a window dragged
      -- small enough the smallest font is still taller than a cell, and a
      -- negative offset would put the top rank's letters above the board.
      local dx = math.floor((cell - gc:getStringWidth(ch)) / 2)
      local dy = math.floor((cell - gc:getStringHeight(ch)) / 2)
      if dx < 0 then dx = 0 end
      if dy < 0 then dy = 0 end
      gc:drawString(ch, bx + c * cell + dx, by + r * cell + dy, "top")
    end
  end
end

-- Every piece of one side, one blit each. The rim travels inside the image, so
-- unlike the run path this needs no layering to keep a piece's outline out of
-- its neighbour: an image is opaque only where the piece is, and the pieces do
-- not overlap.
local function blitPieces(gc, side, inset)
  local cell, bx, by = ui.cell, ui.bx, ui.by
  local list, cnt = game.plist[side], game.pcount[side]
  local imgs, board, TYPE = sprites, game.board, Chess.TYPE
  for i = 1, cnt do
    local sq = list[i]
    local c, r = cellOf(sq)
    gc:drawImage(imgs[TYPE[board[sq]]][side],
      bx + c * cell + inset, by + r * cell + inset)
  end
end

local function drawPieces(gc)
  if not ui.sprites then return drawLetterPieces(gc) end
  local inset = ui.spriteInset
  if sprites then
    blitPieces(gc, WHITE, inset)
    blitPieces(gc, BLACK, inset)
    return
  end
  -- The rim first, then the silhouette over it, so a piece's own outline can
  -- never eat into the piece next to it.
  drawSpriteLayer(gc, WHITE, "edge", W_EDGE, inset)
  drawSpriteLayer(gc, BLACK, "edge", B_EDGE, inset)
  drawSpriteLayer(gc, WHITE, "fill", W_FILL, inset)
  drawSpriteLayer(gc, BLACK, "fill", B_FILL, inset)
end

-- Where the picked-up piece may go. On a board this small, showing every
-- destination is the difference between playing and guessing -- a dot for a
-- quiet move, a ring for a capture, so the two read differently at a glance.
local function drawDests(gc)
  if not sel or nDests == 0 then return end
  local cell, bx, by = ui.cell, ui.bx, ui.by
  local dot = math.max(2, math.floor(cell / 4))
  local inset = math.floor((cell - dot) / 2)
  col(gc, DEST)
  for i = 1, nDests do
    local to = Chess.moveTo(dests[i])
    local c, r = cellOf(to)
    local x, y = bx + c * cell, by + r * cell
    if game.board[to] == Chess.EMPTY and Chess.moveFlag(dests[i]) ~= Chess.FLAG_EP then
      gc:fillArc(x + inset, y + inset, dot, dot, 0, 360)
    else
      gc:drawRect(x + 1, y + 1, cell - 3, cell - 3)
      gc:drawRect(x + 2, y + 2, cell - 5, cell - 5)
    end
  end
end

local function drawCursor(gc)
  if game.state ~= "playing" or phase == "thinking" or promo then return end
  local c, r = cellOf(cursor)
  local x, y = ui.bx + c * ui.cell, ui.by + r * ui.cell
  col(gc, CURSOR)
  gc:drawRect(x, y, ui.cell - 1, ui.cell - 1)
  gc:drawRect(x + 1, y + 1, ui.cell - 3, ui.cell - 3)
end

local function drawLabels(gc)
  if not ui.labels then return end
  gc:setFont("sansserif", "r", 9)
  col(gc, INK_DIM)
  local cell = ui.cell
  for i = 0, 7 do
    local f = string.char(96 + Chess.fileOf(squareAt(i, 7)))
    gc:drawString(f,
      ui.bx + i * cell + math.floor((cell - gc:getStringWidth(f)) / 2),
      ui.by + ui.board + RIM + 1, "top")
    local rk = tostring(Chess.rankOf(squareAt(0, i)))
    gc:drawString(rk,
      math.max(0, ui.bx - RIM - 2 - gc:getStringWidth(rk)),
      ui.by + i * cell + math.floor((cell - gc:getStringHeight(rk)) / 2), "top")
  end
end

-- ----------------------------------------------------------------- sidebar --

local RESULT_TEXT = {
  checkmate  = "Checkmate",
  stalemate  = "Stalemate",
  fifty      = "Draw: 50 moves",
  repetition = "Draw: repetition",
  material   = "Draw: material",
}

local function statusLine()
  if phase == "thinking" then
    -- The depth the bot is on, which is the honest measure of how much of its
    -- budget it has spent. tests/chess/frame.lua reads this string back.
    local d = ai and math.max(1, ai.completedDepth or ai.searchDepth or 1) or 1
    return "Thinking d" .. d, ACCENT
  end
  local r = game.result
  if r then return RESULT_TEXT[r.kind] or "Game over", ACCENT end
  if game.state == "paused" then return "Paused", INK_DIM end
  if game.state == "playing" and game:inCheck() then return "CHECK", CHECK_SQ end
  return nil
end

-- The pieces `side` has taken, as repeated letters, biggest first.
local function takenText(side, out)
  local n = game:capturedBy(side, out)
  local parts = {}
  for t = 5, 1, -1 do
    for _ = 1, n[t] do parts[#parts + 1] = Chess.LETTER[t] end
  end
  return table.concat(parts)
end

local takenBuf = {}

local function drawSidebar(gc)
  if not ui.sidebar then return end
  local x, w = ui.sx, ui.sw
  local top, bottom = ui.by - RIM, ui.by + ui.board + RIM
  local y = top

  -- Every line checks it still has room before it draws. The handheld always
  -- has enough; a window dragged short simply loses the lines at the bottom
  -- rather than spilling over the edge of the board.
  local function line(gc_, text, colour, size, style)
    local h = size + 3
    if y + h > bottom then return false end
    gc_:setFont("sansserif", style or "r", size)
    if gc_:getStringWidth(text) > w then fitFont(gc_, text, w, style or "r") end
    col(gc_, colour)
    gc_:drawString(text, x, y, "top")
    y = y + h
    return true
  end

  -- Whose move it is, as a chip in that side's own colours -- the same disc
  -- treatment as the pieces, so there is nothing to learn.
  local chip = math.min(12, ui.cell - 2)
  if chip >= 6 and y + chip + 2 <= bottom then
    col(gc, (game.side == WHITE) and W_DISC or B_DISC)
    gc:fillArc(x, y + 1, chip, chip, 0, 360)
    col(gc, INK)
    gc:setFont("sansserif", "b", 10)
    local chipText = SIDE_NAME[game.side] .. " to move"
    gc:drawString(chipText, x + chip + 4,
      y + 1 + math.floor((chip - gc:getStringHeight(chipText)) / 2), "top")
    y = y + chip + 4
  end

  local status, statusCol = statusLine()
  if status then line(gc, status, statusCol, 10, "b") end

  if y + 6 <= bottom then
    col(gc, HUD_RULE); gc:drawLine(x, y + 2, x + w, y + 2); y = y + 6
  end

  local wTaken = takenText(WHITE, takenBuf)
  local bTaken = takenText(BLACK, takenBuf)
  local edge = game:materialEdge(WHITE)
  local tag = ""
  if edge > 0 then tag = "  +" .. edge
  elseif edge < 0 then tag = "  " .. edge end
  line(gc, "W takes: " .. ((wTaken ~= "") and wTaken or "-") .. ((edge > 0) and tag or ""),
    INK_DIM, 9)
  line(gc, "B takes: " .. ((bTaken ~= "") and bTaken or "-") .. ((edge < 0) and tag or ""),
    INK_DIM, 9)

  local last = game:lastMove()
  if last then line(gc, "Last: " .. last.text, INK, 10) end
  line(gc, "Move " .. game.full, INK_DIM, 9)

  if y + 6 <= bottom then
    col(gc, HUD_RULE); gc:drawLine(x, y + 2, x + w, y + 2); y = y + 6
  end

  line(gc, "enter  pick / place", INK_DIM, 9)
  line(gc, "U undo    F flip", INK_DIM, 9)
  line(gc, "esc back  M menu", INK_DIM, 9)
end

-- ---------------------------------------------------------------- overlays --

-- lines: array of { text, dim, marked } -- dim entries blink, as on Snake's
-- panels, and a marked one gets the caret in the gutter.
--
-- `leftAlign` is for the menu. Centring rows whose text changes length as the
-- values cycle makes every row jump sideways when any one of them is altered,
-- which reads as the panel twitching rather than as a setting changing.
local function drawPanel(gc, title, lines, accent, leftAlign)
  gc:setFont("sansserif", "b", 16)
  local titleW = gc:getStringWidth(title)

  gc:setFont("sansserif", "r", 10)
  local maxW = titleW
  for _, l in ipairs(lines) do
    local lw = gc:getStringWidth(l[1])
    if lw > maxW then maxW = lw end
  end

  local gutter = leftAlign and 10 or 0
  maxW = maxW + gutter
  local pad, lineH = 10, 13
  -- Clamp to the window: the handheld is always wide enough, but the computer
  -- software can be resized smaller than the panel's natural size, and the
  -- Nspire clips silently rather than complaining.
  local bw = math.min(maxW + pad * 2, ui.w - 4)
  local bh = math.min(22 + #lines * lineH + pad * 2, ui.h - HUD_H - 4)
  local bx = math.max(2, math.floor((ui.w - bw) / 2))
  local by = math.max(HUD_H + 2, math.floor((ui.h - bh) / 2) + math.floor(HUD_H / 2))

  col(gc, PANEL_BG); gc:fillRect(bx, by, bw, bh)
  col(gc, accent); gc:drawRect(bx, by, bw, bh)

  gc:setFont("sansserif", "b", 16)
  col(gc, accent)
  gc:drawString(title, bx + math.floor((bw - titleW) / 2), by + pad - 2, "top")

  gc:setFont("sansserif", "r", 10)
  local y = by + pad + 20
  local lit = (blink % 16) < 10
  for _, l in ipairs(lines) do
    if l[3] then
      col(gc, accent)
      gc:fillRect(bx + pad, y + 4, 5, 5)
    end
    if l[2] and not lit then col(gc, INK_DIM)
    elseif l[2] or l[3] then col(gc, INK)
    else col(gc, INK_DIM) end
    local tx = leftAlign and (bx + pad + gutter)
      or (bx + math.floor((bw - gc:getStringWidth(l[1])) / 2))
    gc:drawString(l[1], tx, y, "top")
    y = y + lineH
  end
  return bx, by, bw, bh
end

-- The rows that do not apply to the chosen mode read "--" rather than
-- vanishing: a menu that changes shape as you move through it is harder to
-- learn than one that always shows the same four things.
local function menuLines()
  local hot = (menu.mode == 1)
  return {
    { "Players: " .. MODE_NAMES[menu.mode], false, menu.row == 1 },
    { "Level: " .. (hot and "--" or level().name), false, menu.row == 2 },
    { "Play as: " .. (hot and "--" or SIDE_NAME[menu.side]), false, menu.row == 3 },
    { "Turn board: " .. (hot and ONOFF[menu.autoFlip] or "--"), false, menu.row == 4 },
    { "arrows choose    enter starts", true },
  }
end

-- The promotion chooser. Four pieces, drawn the way they will look on the
-- board, because "Q R B N" as bare text next to a board full of discs is a
-- second visual language to learn for no reason.
local function drawPromoPanel(gc)
  local side = game.side
  local cell = math.max(SPRITE_PX + 4, math.min(ui.cell + 6, 28))
  local hint = "arrows pick    enter takes it"
  -- Wide enough for the four pieces *and* for the hint under them, measured
  -- rather than guessed: the hint is the longer of the two at every cell size
  -- the handheld actually uses.
  gc:setFont("sansserif", "r", 9)
  local bw = math.max(cell * 4 + 24, gc:getStringWidth(hint) + 20)
  bw = math.min(bw, ui.w - 4)
  local bh = cell + 46
  local bx = math.max(2, math.floor((ui.w - bw) / 2))
  local by = math.max(HUD_H + 2, math.floor((ui.h - bh) / 2))

  col(gc, PANEL_BG); gc:fillRect(bx, by, bw, bh)
  col(gc, ACCENT); gc:drawRect(bx, by, bw, bh)

  gc:setFont("sansserif", "b", 10)
  local title = "Promote to"
  col(gc, ACCENT)
  gc:drawString(title, bx + math.floor((bw - gc:getStringWidth(title)) / 2), by + 5, "top")

  local sx = bx + math.floor((bw - cell * 4) / 2)
  local sy = by + 21
  for i = 1, 4 do
    local x = sx + (i - 1) * cell
    if i == promo.choice then
      col(gc, ACCENT); gc:fillRect(x, sy, cell, cell)
    end
    -- The same sprites as the board, so there is no second visual language
    -- to learn at the one moment the player has to make a choice.
    drawSprite(gc, Chess.PROMO_PIECES[i], side,
      x + math.floor((cell - SPRITE_PX) / 2), sy + math.floor((cell - SPRITE_PX) / 2))
  end

  gc:setFont("sansserif", "r", 9)
  col(gc, INK_DIM)
  gc:drawString(hint, bx + math.floor((bw - gc:getStringWidth(hint)) / 2),
    sy + cell + 4, "top")
end

local function overText()
  local r = game.result
  if not r then return "GAME OVER", {} end
  if r.kind == "checkmate" then
    return "CHECKMATE", { { SIDE_NAME[r.winner] .. " wins" } }
  elseif r.kind == "stalemate" then
    return "STALEMATE", { { "Draw -- no legal move, no check" } }
  elseif r.kind == "fifty" then
    return "DRAW", { { "Fifty moves without a capture" }, { "or a pawn move" } }
  elseif r.kind == "repetition" then
    return "DRAW", { { "Same position three times" } }
  end
  return "DRAW", { { "Neither side can force mate" } }
end

local function drawOverlay(gc)
  if game.state == "ready" then
    drawPanel(gc, "CHESS", menuLines(), ACCENT, true)
  elseif promo then
    drawPromoPanel(gc)
  elseif game.state == "paused" then
    drawPanel(gc, "PAUSED", {
      { SIDE_NAME[game.side] .. " to move" },
      { "Press enter to resume", true },
    }, ACCENT)
  elseif game:isOver() then
    local title, lines = overText()
    lines[#lines + 1] = { "enter plays again   esc menu", true }
    drawPanel(gc, title, lines, ACCENT)
  end
end

function on.paint(gc)
  col(gc, PAGE); gc:fillRect(0, 0, ui.w, ui.h)
  drawSquares(gc)
  drawHighlights(gc)
  drawPieces(gc)
  drawDests(gc)
  drawCursor(gc)
  drawLabels(gc)
  drawSidebar(gc)
  drawHud(gc)
  drawOverlay(gc)
end
